import {RATE_TTL,canonicalCurrency,marketKey,selectQuote,quoteProvenance,validateSnapshot} from './market-rates.mjs';
export function createMarketController({store,persist,modal,toast,esc,$,currencies,onUpdate}){
 const names={ninja:'poe.ninja',scout:'PoE2 Scout'};let busy=false,error='',generation=0,lastAttempt=0,dialogSequence=0;const leagueCache=new Map();
 store.market=store.market&&typeof store.market==='object'?store.market:{};const s=store.market;s.enabled=s.enabled!==false;s.auto=s.auto!==false;s.provider=['ninja','scout'].includes(s.provider)?s.provider:'ninja';s.league=typeof s.league==='string'?s.league:'';s.snapshots=s.snapshots||{};s.overrides=s.overrides||{};
 for(const [key,snapshot] of Object.entries(s.snapshots)){try{s.snapshots[key]=validateSnapshot(snapshot)}catch{delete s.snapshots[key]}}
 const endpoint=(path,provider,league)=>{if(location.protocol==='file:')throw Error('Для синхронизации откройте онлайн-версию или запустите npm start. Автономный HTML использует сохранённые курсы.');const u=new URL('/api/market/'+path,location.origin);u.searchParams.set('provider',provider);if(league)u.searchParams.set('league',league);return u.toString()};
 const request=async(path,provider,league)=>{const r=await fetch(endpoint(path,provider,league),{signal:AbortSignal.timeout(55000),headers:{Accept:'application/json'}});let data;try{data=await r.json()}catch{throw Error('Сервер курсов недоступен. Для локального запуска используйте npm start.')}if(!r.ok)throw Error(data.error||'Не удалось получить курсы');return data};
 const date=t=>Number.isFinite(Date.parse(t))?new Date(t).toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'}):'нет данных';
 const quote=currency=>selectQuote(s,store.rates,currency);
 const provenance=(currency,value,q)=>quoteProvenance(q||quote(currency),value);
 function snapshot(){return s.snapshots[marketKey(s.provider,s.league)]}
 function summary(){if(!s.enabled)return 'Ручные курсы';if(busy)return 'Загружаю курсы…';const snap=snapshot();if(!snap)return error||'Курсы ещё не загружены';const age=Date.now()-Date.parse(snap.fetchedAt);return `${names[s.provider]} · ${s.league} · загружено ${date(snap.fetchedAt)}${age>RATE_TTL?' · сохранённый снимок':''}${snap.partial?' · неполное покрытие':''}${error?' · обновление недоступно':''}`}
 function barHTML(){return `<div class="market-bar" id="market-bar"><span><span class="green-dot"></span><strong>Курсы валют</strong> <span class="market-summary">${esc(summary())}</span></span><button class="text-button" id="market-open">Источник и лига ↗</button></div>`}
 function paint(){const el=$('#market-bar .market-summary');if(el)el.textContent=summary()}
 function bind(){if($('#market-open'))$('#market-open').onclick=open}
 function notify(){persist();paint();onUpdate?.()}
 async function getLeagues(provider){const old=leagueCache.get(provider);if(old&&Date.now()-old.at<RATE_TTL)return old.data;const data=await request('leagues',provider);if(!Array.isArray(data.leagues)||!data.leagues.length)throw Error('Источник не вернул лиги');leagueCache.set(provider,{at:Date.now(),data:data.leagues});return data.leagues}
 async function refresh({quiet=false}={}){if(busy)return;if(!s.enabled)return;const id=++generation;busy=true;error='';lastAttempt=Date.now();paint();try{const provider=s.provider;const leagues=await getLeagues(provider);if(id!==generation||provider!==s.provider)return;if(!s.league||!leagues.some(l=>l.id===s.league)){s.league=leagues.find(l=>l.current&&!/^HC |Hardcore/.test(l.id))?.id||leagues[0].id}const league=s.league;const data=validateSnapshot(await request('rates',provider,league));if(id!==generation||s.provider!==provider||s.league!==league)return;if(data.provider!==provider||data.league!==league)throw Error('Ответ относится к другой лиге');s.snapshots[marketKey(provider,league)]=data;const keys=Object.keys(s.snapshots);while(keys.length>12)delete s.snapshots[keys.shift()];if(!quiet)toast(`Курсы обновлены: ${data.quotes.length} котировок`)}catch(e){if(id===generation)error=e.name==='TimeoutError'?'Источник не ответил вовремя. Сохранённые курсы оставлены.':e.message;if(!quiet)toast(error)}finally{if(id===generation){busy=false;notify()}}}
 function hint(currency){const q=quote(currency);if(q.value===null)return 'Нет курса — введите стоимость вручную';if(q.origin==='base')return 'Опорная валюта · 1 ex';if(q.origin==='manual')return `Ручной курс${q.league?' · '+q.league:''}`;return `${names[q.provider]} · ${q.league} · ${date(q.fetchedAt)}${q.stale?' · сохранённый курс':''}`}
 function priceHTML(currency){const q=quote(currency);return q.value===null?'':`<span class="price-hint" title="${esc(hint(currency))}">≈ ${q.value.toLocaleString('ru-RU',{maximumFractionDigits:4})} ex · ${esc(q.origin==='market'?names[q.provider]:'ручной курс')}</span>`}
 async function open(){
  let localProvider=s.provider,localLeague=s.league,list=leagueCache.get(localProvider)?.data||[],dialogGeneration=0;const viewId=++dialogSequence;
  modal('Курсы валют и источник',`<div class="two-fields"><div class="field"><label for="market-provider">Источник</label><select id="market-provider">${Object.entries(names).map(([k,n])=>`<option value="${k}" ${k===s.provider?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="market-league">Лига</label><select id="market-league"><option value="">Загружаю лиги…</option></select></div></div><label class="checkline"><input id="market-enabled" type="checkbox" ${s.enabled?'checked':''}> Подставлять рыночные курсы в новые расходы</label><label class="checkline"><input id="market-auto" type="checkbox" ${s.auto?'checked':''}> Обновлять каждые 30 минут, пока приложение открыто</label><p class="section-note" id="market-dialog-status">${esc(summary())}</p><div class="actions"><button class="button secondary small" id="market-sync">Обновить сейчас</button><button class="button secondary small" id="market-export">Экспорт снимка</button><button class="button secondary small" id="market-import">Импорт снимка</button></div><input type="file" id="market-import-file" accept="application/json,.json" hidden><input class="search-input" id="market-search" aria-label="Поиск курса валюты" style="margin-top:15px" placeholder="Валюта, омен, эссенция…"><div class="market-table-head"><span>Валюта</span><span>API / ex</span><span>Ваш курс / ex</span></div><div id="market-table" class="picker-list market-table"></div><p class="section-note">Ручное значение перекрывает API только для выбранных источника и лиги. Пустое поле использует API. Котировки — ориентир, цена вашей сделки может отличаться. Старые расходы не пересчитываются. <a href="https://poe.ninja/docs/api" target="_blank" rel="noopener">API poe.ninja</a> · <a href="https://api.poe2scout.com/swagger" target="_blank" rel="noopener">API Scout</a></p><p class="error" id="market-error"></p>`,'<button class="button" id="market-save">Сохранить настройки</button>');
  $('#modal').addEventListener('close',()=>onUpdate?.(),{once:true});const draftOverrides=new Map();
  function key(){return marketKey(localProvider,localLeague)}
  function drafts(){if(!draftOverrides.has(key()))draftOverrides.set(key(),{...(s.overrides[key()]||{})});return draftOverrides.get(key())}
  function fillTable(){const snap=s.snapshots[key()],query=$('#market-search').value.toLowerCase();const available=currencies.filter(([id,name])=>(id+' '+name).toLowerCase().includes(query));const cfg={...s,enabled:true,provider:localProvider,league:localLeague,overrides:{...s.overrides,[key()]:{}}};$('#market-table').innerHTML=available.map(([id,name])=>{const q=selectQuote(cfg,{},id),manual=drafts()[canonicalCurrency(id)];const base=canonicalCurrency(id)==='exaltedorb';return `<div class="market-rate-row"><span>${esc(name)}<small>${esc(id)}</small></span><span class="muted">${q.value===null?'—':q.value.toLocaleString('ru-RU',{maximumFractionDigits:4})}</span><input type="number" min="0" max="1000000000" step="any" data-market-override="${esc(id)}" aria-label="Ручной курс: ${esc(name)}" value="${manual??''}" placeholder="API" ${base?'disabled':''}></div>`}).join('');document.querySelectorAll('[data-market-override]').forEach(el=>el.oninput=()=>{const k=canonicalCurrency(el.dataset.marketOverride);if(el.value==='')delete drafts()[k];else drafts()[k]=Number(el.value)});const stamp=snap?`Загружено ${date(snap.fetchedAt)} · ${snap.quotes.length} котировок${snap.partial?' · часть категорий недоступна':''}`:'Для этой лиги нет сохранённого снимка';$('#market-dialog-status').textContent=stamp;}
  async function loadLeagues(){const token=++dialogGeneration;$('#market-error').textContent='';try{list=await getLeagues(localProvider);if(token!==dialogGeneration||viewId!==dialogSequence||!$('#market-provider'))return;if(!list.some(l=>l.id===localLeague))localLeague=list.find(l=>l.current&&!/^HC |Hardcore/.test(l.id))?.id||list[0].id;$('#market-league').innerHTML=list.map(l=>`<option value="${esc(l.id)}" ${l.id===localLeague?'selected':''}>${esc(l.name)}</option>`).join('');fillTable()}catch(e){if(token!==dialogGeneration||viewId!==dialogSequence||!$('#market-error'))return;$('#market-error').textContent=e.message;$('#market-league').innerHTML=localLeague?`<option value="${esc(localLeague)}">${esc(localLeague)} (сохранено)</option>`:'<option value="">Нет соединения</option>';fillTable()}}
  $('#market-provider').onchange=()=>{localProvider=$('#market-provider').value;loadLeagues()};$('#market-league').onchange=()=>{localLeague=$('#market-league').value;fillTable()};$('#market-search').oninput=fillTable;
  const saveSettings=()=>{for(const [,values] of draftOverrides)for(const v of Object.values(values))if(!Number.isFinite(v)||v<0||v>1e9)throw Error('Ручной курс должен быть от 0 до 1 000 000 000');if($('#market-enabled').checked&&!localLeague)throw Error('Сначала выберите лигу');generation++;busy=false;s.enabled=$('#market-enabled').checked;s.auto=$('#market-auto').checked;s.provider=localProvider;s.league=localLeague;for(const [k,v] of draftOverrides)s.overrides[k]=v;notify()};
  $('#market-save').onclick=()=>{try{saveSettings();$('#modal').close();toast('Настройки курсов сохранены');if(s.enabled&&!snapshot())refresh({quiet:true})}catch(e){$('#market-error').textContent=e.message}};
  $('#market-sync').onclick=async()=>{try{saveSettings();$('#market-sync').disabled=true;await refresh();if($('#market-sync')){fillTable();$('#market-error').textContent=error}}catch(e){if($('#market-error'))$('#market-error').textContent=e.message}finally{if($('#market-sync'))$('#market-sync').disabled=false}};
  $('#market-export').onclick=()=>{const snap=s.snapshots[key()];if(!snap){$('#market-error').textContent='Сначала загрузите курсы выбранной лиги';return}const url=URL.createObjectURL(new Blob([JSON.stringify({format:'wraeclast-forge-rates',version:1,snapshot:snap})],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='forge-rates-'+localProvider+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  $('#market-import').onclick=()=>$('#market-import-file').click();$('#market-import-file').onchange=async()=>{try{const f=$('#market-import-file').files[0];if(!f)return;if(f.size>2e6)throw Error('Файл слишком большой');const d=JSON.parse(await f.text());if(d.format!=='wraeclast-forge-rates'||d.version!==1)throw Error('Неверный формат снимка');const snap=validateSnapshot(d.snapshot);s.snapshots[marketKey(snap.provider,snap.league)]=snap;localProvider=snap.provider;localLeague=snap.league;$('#market-provider').value=localProvider;persist();await loadLeagues();fillTable();toast('Снимок курсов импортирован')}catch(e){$('#market-error').textContent=e.message}};
  fillTable();loadLeagues();
 }
 function start(){if(location.protocol==='file:')return;if(s.enabled)refresh({quiet:true});setInterval(()=>{if(s.auto&&s.enabled&&!document.hidden&&Date.now()-lastAttempt>=RATE_TTL)refresh({quiet:true})},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&s.auto&&s.enabled&&Date.now()-lastAttempt>=RATE_TTL)refresh({quiet:true})})}
 return {quote,provenance,hint,priceHTML,barHTML,paint,bind,open,refresh,start};
}
